 "content": "def transform(grid):
    """Complete sparse repeated panel motifs by the demonstrated reflections."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Full nonzero uniform lines are panel separators.
    hr = [r for r, row in enumerate(g) if row[0] != 0 and all(v == row[0] for v in row)]
    vc = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]
    def spans(size, cuts):
        bounds = [-1] + cuts + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]
    rowspans, colspans = spans(h, hr), spans(w, vc)
    sep_colors = set()
    for r in hr:
        sep_colors.add(g[r][0])
    for c in vc:
        sep_colors.add(g[0][c])
    # Operate independently by motif color, avoiding separator and background colors.
    colors = {v for row in g for v in row if v not in (0,) | sep_colors}
    for color in colors:
        # In a panel row with a sole occupied panel, continue it into the next panel
        # as a horizontal reflection (the established one-source completion rule).
        for r0, r1 in rowspans:
            occupied = []
            for j, (c0, c1) in enumerate(colspans):
                if any(g[r][c] == color for r in range(r0, r1) for c in range(c0, c1)):
                    occupied.append(j)
            if len(occupied) == 1:
                j = occupied[0]
                if j + 1 < len(colspans):
                    c0, c1 = colspans[j]
                    d0, d1 = colspans[j + 1]
                    if r1 - r0 == r1 - r0 and c1 - c0 == d1 - d0:
                        coords = [(r, c) for r in range(r0, r1) for c in range(c0, c1) if g[r][c] == color]
                        for r, c in coords:
                            g[r][d1 - 1 - (c - c0)] = color
        # Where consecutive panel rows contain the same set of occupied panels,
        # complete the lower row with a vertical reflection of the upper motifs.
        for i in range(len(rowspans) - 1):
            a0, a1 = rowspans[i]
            b0, b1 = rowspans[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            def occupied_cols(r0, r1):
                return {j for j, (c0, c1) in enumerate(colspans)
                        if any(g[r][c] == color for r in range(r0, r1) for c in range(c0, c1))}
            upper, lower = occupied_cols(a0, a1), occupied_cols(b0, b1)
            if upper and upper == lower:
                for j in upper:
                    c0, c1 = colspans[j]
                    for r in range(a0, a1):
                        for c in range(c0, c1):
                            if g[r][c] == color:
                                g[b1 - 1 - (r - a0)][c] = color
    return g
