                        if any(out[r][c] == color for r in range(r0, r1) for c in range(c0, c1))]
            if not occupied:
                continue
            source_index = occupied[0]
            # Four-panel layouts have two central panels. The motif advances
            # from its side toward the center, reflecting across the panel width.
            if len(col_panels) == 4:
                target_index = {0: 1, 1: 2, 2: 1, 3: 2}[source_index]
            else:
                target_index = source_index + 1 if source_index + 1 < len(col_panels) else source_index - 1
