    """Copy a motif to its homologous panel, reflecting it across panel width."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    sep_rows = [r for r in range(h) if out[r][0] != 0 and len(set(out[r])) == 1]
    sep_cols = [c for c in range(w) if out[0][c] != 0 and all(out[r][c] == out[0][c] for r in range(h))]

    def spans(n, cuts):
        edges = [-1] + cuts + [n]
        return [(edges[i] + 1, edges[i + 1]) for i in range(len(edges) - 1)]

    row_panels = spans(h, sep_rows)
    col_panels = spans(w, sep_cols)
    separator_colors = {out[r][0] for r in sep_rows} | {out[0][c] for c in sep_cols}
    colors = {v for row in out for v in row if v != 0 and v not in separator_colors}

    for color in colors:
        for r0, r1 in row_panels:
            occupied = [j for j, (c0, c1) in enumerate(col_panels)
                        if any(out[r][c] == color for r in range(r0, r1) for c in range(c0, c1))]
            if not occupied:
                continue
            # A pattern aligned to the right in the left panel mirrors into
            # the right-aligned position of the next panel, and vice versa.
            if len(col_panels) == 3:
                target_index = 1 if occupied[0] == 0 else 1
            elif len(col_panels) == 4:
                target_index = {0: 1, 1: 2, 2: 1, 3: 2}[occupied[0]]
            else:
                target_index = occupied[0] + 1 if occupied[0] + 1 < len(col_panels) else occupied[0] - 1
            s0, s1 = col_panels[occupied[0]]
            d0, d1 = col_panels[target_index]
            if s1 - s0 != d1 - d0:
                continue
            # Copy regardless of other marks; the geometric motif is overlaid.
            for r in range(r0, r1):
                for c in range(s0, s1):
                    if out[r][c] == color:
                        out[r][d0 + (d1 - d0 - 1) - (c - s0)] = color
    return out
