    """Complete horizontally mirrored panel pairs and propagate them vertically."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    rowcuts = [r for r in range(h) if out[r][0] != 0 and len(set(out[r])) == 1]
    colcuts = [c for c in range(w) if out[0][c] != 0 and all(out[r][c] == out[0][c] for r in range(h))]

    def spans(n, cuts):
        edges = [-1] + cuts + [n]
        return [(edges[i] + 1, edges[i + 1]) for i in range(len(edges) - 1)]

    row_panels = spans(h, rowcuts)
    col_panels = spans(w, colcuts)
    separators = {out[r][0] for r in rowcuts} | {out[0][c] for c in colcuts}
    colors = {v for row in out for v in row if v != 0 and v not in separators}
    original = [row[:] for row in out]

    def cells(color, ri, ci):
        r0, r1 = row_panels[ri]
        c0, c1 = col_panels[ci]
        return {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                if original[r][c] == color}

    def hflip(p, width):
        return {(r, width-1-c) for r, c in p}

    def vflip(p, height):
        return {(height-1-r, c) for r, c in p}

    def paint(color, ri, ci, pat):
        r0, r1 = row_panels[ri]
        c0, c1 = col_panels[ci]
        for r, c in pat:
            if 0 <= r < r1-r0 and 0 <= c < c1-c0 and out[r0+r][c0+c] == 0:
                out[r0+r][c0+c] = color

    handled = set()
    # If a complete horizontal mirror pair in one band has a vertical counterpart
    # in the adjacent band, continue the vertical reflection and fill its missing side.
    for color in colors:
        for ri in range(len(row_panels)-1):
            r0, r1 = row_panels[ri]
            nr0, nr1 = row_panels[ri+1]
            if r1-r0 != nr1-nr0:
                continue
            for ci in range(len(col_panels)-1):
                a0, a1 = col_panels[ci]
                b0, b1 = col_panels[ci+1]
                width = a1-a0
                if width != b1-b0 or width != r1-r0:
                    continue
                upper_a, upper_b = cells(color, ri, ci), cells(color, ri, ci+1)
                if not upper_a or upper_b != hflip(upper_a, width):
                    continue
                lower_a, lower_b = cells(color, ri+1, ci), cells(color, ri+1, ci+1)
                expected_a, expected_b = vflip(upper_a, r1-r0), vflip(upper_b, r1-r0)
                if lower_a == expected_a and not lower_b:
                    paint(color, ri+1, ci+1, expected_b)
                    handled.add((color, ri+1, ci+1))
                elif lower_b == expected_b and not lower_a:
                    paint(color, ri+1, ci, expected_a)
                    handled.add((color, ri+1, ci))
                elif lower_a == expected_a and lower_b == expected_b:
                    handled.add((color, ri+1, ci)); handled.add((color, ri+1, ci+1))

    # A lone square motif at the outer side of a panel row initiates its inward mirror.
    # Do not override a side already governed by a vertical counterpart above.
    for color in colors:
        for ri, (r0, r1) in enumerate(row_panels):
            marked = [ci for ci, (c0, c1) in enumerate(col_panels) if cells(color, ri, ci)]
            if len(marked) != 1 or r1-r0 == 0:
                continue
            src = marked[0]
            if len(col_panels) == 4:
                dst = {0: 1, 1: 2, 2: 1, 3: 2}[src]
            else:
                dst = src+1 if src+1 < len(col_panels) else src-1
            if (color, ri, src) in handled or (color, ri, dst) in handled:
