            s0, s1 = col_panels[src]
            d0, d1 = col_panels[dst]
            if s1-s0 != d1-d0 or s1-s0 != r1-r0:
                continue
            source = cells(color, ri, src)
            if not source or cells(color, ri, dst):
                continue
            paint(color, ri, dst, hflip(source, s1-s0))
    return out
