        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    rp, cp = spans(h, rowcuts), spans(w, colcuts)
    sepcolors = {out[r][0] for r in rowcuts} | {out[0][c] for c in colcuts}
    colors = {v for row in out for v in row if v != 0 and v not in sepcolors}
    original = [row[:] for row in out]

    def get(color, ri, ci):
        r0, r1 = rp[ri]; c0, c1 = cp[ci]
        return {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                if original[r][c] == color}

    def H(p, width): return {(r, width-1-c) for r,c in p}
    def V(p, height): return {(height-1-r, c) for r,c in p}
    def HV(p, height, width): return {(height-1-r, width-1-c) for r,c in p}

    def place(color, ri, ci, pattern):
        r0, r1 = rp[ri]; c0, c1 = cp[ci]
        for r,c in pattern:
            if 0 <= r < r1-r0 and 0 <= c < c1-c0 and out[r0+r][c0+c] == 0:
                out[r0+r][c0+c] = color

    for color in colors:
        # Three occupied matching corners determine the fourth by reflection.
        for ri in range(len(rp)-1):
            rh = rp[ri][1] - rp[ri][0]
            if rp[ri+1][1] - rp[ri+1][0] != rh:
                continue
            for ci in range(len(cp)-1):
                cw = cp[ci][1] - cp[ci][0]
                if cp[ci+1][1] - cp[ci+1][0] != cw or rh != cw:
                    continue
                pats = [get(color,ri,ci), get(color,ri,ci+1),
                        get(color,ri+1,ci), get(color,ri+1,ci+1)]
                # Normalize all corners back to the top-left motif.
                canonical = [pats[0], H(pats[1],cw), V(pats[2],rh), HV(pats[3],rh,cw)]
