    """Fill sparse panel motifs by reflecting corresponding occupied panels."""
    out = [row[:] for row in grid]
    h,w=len(out),len(out[0])
    hr=[r for r in range(h) if out[r][0] and len(set(out[r]))==1]
    vc=[c for c in range(w) if out[0][c] and all(out[r][c]==out[0][c] for r in range(h))]
    def spans(n,cuts):
        b=[-1]+cuts+[n]
        return [(b[i]+1,b[i+1]) for i in range(len(b)-1)]
    rp,cp=spans(h,hr),spans(w,vc)
    sep={out[r][0] for r in hr}|{out[0][c] for c in vc}
    colors={v for row in out for v in row if v and v not in sep}
    src=[row[:] for row in out]
    for color in colors:
        for i,(r0,r1) in enumerate(rp):
            occupied=[j for j,(c0,c1) in enumerate(cp) if any(src[r][c]==color for r in range(r0,r1) for c in range(c0,c1))]
            if len(occupied)==1:
                j=occupied[0]
                # The source panel points inward; its motif is horizontally mirrored.
                k=j+1 if j+1<len(cp) else j-1
                c0,c1=cp[j];d0,d1=cp[k]
                if c1-c0==d1-d0:
                    for r in range(r0,r1):
                        for c in range(c0,c1):
                            if src[r][c]==color:
                                out[r][d0+(d1-d0-1)-(c-c0)]=color
        # A second panel row can carry the missing vertical reflection of an
        # already mirrored motif, but only where the paired source exists.
        for i in range(len(rp)-1):
            r0,r1=rp[i];q0,q1=rp[i+1]
            if r1-r0!=q1-q0: continue
            for j in range(len(cp)-1):
                c0,c1=cp[j];d0,d1=cp[j+1]
                if c1-c0!=d1-d0: continue
                A={(r-r0,c-c0) for r in range(r0,r1) for c in range(c0,c1) if src[r][c]==color}
                B={(r-r0,c-d0) for r in range(r0,r1) for c in range(d0,d1) if src[r][c]==color}
                if not A or not B: continue
                # The adjacent motifs form a paired panel pattern; reflect either
                # panel vertically only where that corresponding panel is empty.
                for colbase,P in ((c0,A),(d0,B)):
                    if any(src[r][c]==color for r in range(q0,q1) for c in range(colbase,colbase+(c1-c0))): continue
                    for r,c in P:
                        out[q0+(r1-r0-1-r)][colbase+c]=color
    return out
