    """Complete 2x2 panel motifs by matching horizontal/vertical reflections."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    rowcuts = [r for r in range(h) if out[r][0] != 0 and len(set(out[r])) == 1]
    colcuts = [c for c in range(w) if out[0][c] != 0 and all(out[r][c] == out[0][c] for r in range(h))]

    def spans(n, cuts):
        b = [-1] + cuts + [n]
        return [(b[i] + 1, b[i + 1]) for i in range(len(b) - 1)]

    rp, cp = spans(h, rowcuts), spans(w, colcuts)
    divider = {out[r][0] for r in rowcuts} | {out[0][c] for c in colcuts}
    colors = {v for row in out for v in row if v != 0 and v not in divider}
    original = [row[:] for row in out]

    def pattern(color, ri, ci):
        r0, r1 = rp[ri]; c0, c1 = cp[ci]
        return {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                if original[r][c] == color}

    def hflip(p, width): return {(r, width-1-c) for r, c in p}
    def vflip(p, height): return {(height-1-r, c) for r, c in p}
    def hvflip(p, height, width): return {(height-1-r, width-1-c) for r, c in p}

    for color in colors:
        for ri in range(len(rp)-1):
            r0, r1 = rp[ri]; nr0, nr1 = rp[ri+1]
