                width = c1-c0
                if width != nc1-nc0:
                    continue
                pats = [pattern(color,ri,ci), pattern(color,ri,ci+1),
                        pattern(color,ri+1,ci), pattern(color,ri+1,ci+1)]
                canonical = [pats[0], hflip(pats[1],width),
                            vflip(pats[2],height), hvflip(pats[3],height,width)]
                present = [i for i,p in enumerate(pats) if p]
