    """Reflect every motif to its adjacent panel partner in both axes."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    rowcuts = [r for r in range(h) if out[r][0] != 0 and len(set(out[r])) == 1]
    colcuts = [c for c in range(w) if out[0][c] != 0 and all(out[r][c] == out[0][c] for r in range(h))]
    def spans(n,cuts):
        b=[-1]+cuts+[n]
        return [(b[i]+1,b[i+1]) for i in range(len(b)-1)]
    rp,cp=spans(h,rowcuts),spans(w,colcuts)
    separators={out[r][0] for r in rowcuts}|{out[0][c] for c in colcuts}
    colors={x for row in out for x in row if x and x not in separators}
    src=[row[:] for row in out]
    # Repeated layout is a 4x4 tiling: mirror the two-panel motif blocks across
    # the four panel-row/column pair boundaries, preserving existing colored cells.
    for color in colors:
        for ri,(r0,r1) in enumerate(rp):
            for ci,(c0,c1) in enumerate(cp):
