            for ci,(c0,c1) in enumerate(cp):
                if not any(src[r][c]==color for r in range(r0,r1) for c in range(c0,c1)):continue
                # copy toward center in a four-panel arrangement, otherwise to the next panel
                if len(cp)==4: dst={0:1,1:2,2:1,3:2}[ci]
