    """Copy motifs to every sibling panel by preserving panel-relative offsets."""
    out = [row[:] for row in grid]
    h,w=len(out),len(out[0])
    hr=[r for r in range(h) if out[r][0] and len(set(out[r]))==1]
    vc=[c for c in range(w) if out[0][c] and all(out[r][c]==out[0][c] for r in range(h))]
    def spans(n,cuts):
        b=[-1]+cuts+[n]
        return [(b[i]+1,b[i+1]) for i in range(len(b)-1)]
    rp,cp=spans(h,hr),spans(w,vc)
    div={out[r][0] for r in hr}|{out[0][c] for c in vc}
    colors={x for row in out for x in row if x and x not in div}
    original=[row[:] for row in out]
    for color in colors:
        for ri,(r0,r1) in enumerate(rp):
            occ=[j for j,(c0,c1) in enumerate(cp) if any(original[r][c]==color for r in range(r0,r1) for c in range(c0,c1))]
            # Extend any pattern occupying a panel to all other panels in the band,
            # by the same horizontal mirror rule shown by matched neighboring panels.
            for j in occ:
                c0,c1=cp[j]
                for k,(d0,d1) in enumerate(cp):
                    if k==j or c1-c0!=d1-d0:continue
                    for r in range(r0,r1):
                        for c in range(c0,c1):
                            if original[r][c]==color:
                                out[r][d0+(d1-d0-1)-(c-c0)]=color
    return out
