 "content": "def transform(grid):
    """Complete reflection-linked motif panels in adjacent 2x2 panel blocks."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    rowcuts = [r for r in range(h) if out[r][0] != 0 and len(set(out[r])) == 1]
    colcuts = [c for c in range(w) if out[0][c] != 0 and all(out[r][c] == out[0][c] for r in range(h))]

    def spans(n, cuts):
        edges = [-1] + cuts + [n]
        return [(edges[i] + 1, edges[i + 1]) for i in range(len(edges) - 1)]

    rp, cp = spans(h, rowcuts), spans(w, colcuts)
    separators = {out[r][0] for r in rowcuts} | {out[0][c] for c in colcuts}
    colors = {v for row in out for v in row if v != 0 and v not in separators}
    original = [row[:] for row in out]

    def get(color, ri, ci):
        r0, r1 = rp[ri]
        c0, c1 = cp[ci]
        return {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                if original[r][c] == color}

    def H(p, width): return {(r, width-1-c) for r,c in p}
    def V(p, height): return {(height-1-r, c) for r,c in p}
    def HV(p, height, width): return {(height-1-r, width-1-c) for r,c in p}

    def fill(color, ri, ci, pattern):
        r0, r1 = rp[ri]
        c0, c1 = cp[ci]
        for r,c in pattern:
            if 0 <= r < r1-r0 and 0 <= c < c1-c0 and out[r0+r][c0+c] == 0:
                out[r0+r][c0+c] = color

    for color in colors:
        for ri in range(len(rp)-1):
            r0,r1=rp[ri]; nr0,nr1=rp[ri+1]
            height=r1-r0
            if height != nr1-nr0: continue
            for ci in range(len(cp)-1):
                c0,c1=cp[ci]; d0,d1=cp[ci+1]
                width=c1-c0
                if width != d1-d0: continue
                p00=get(color,ri,ci); p01=get(color,ri,ci+1)
                p10=get(color,ri+1,ci); p11=get(color,ri+1,ci+1)
                patterns=[p00,p01,p10,p11]
                canonical=[p00,H(p01,width),V(p10,height),HV(p11,height,width)]
                present=[i for i,p in enumerate(patterns) if p]
                # Complete a missing corner if the other three are the same motif
                # under horizontal/vertical reflection.
                if len(present)==3:
                    base=canonical[present[0]]
                    if base and all(canonical[i]==base for i in present[1:]):
                        missing=next(i for i in range(4) if i not in present)
                        predicted=[base,H(base,width),V(base,height),HV(base,height,width)][missing]
                        fill(color,ri+missing//2,ci+missing%2,predicted)
                # A complete mirrored pair copied vertically into a blank band.
                elif len(present)==2 and {i//2 for i in present} in ({0},{1}):
                    row=0 if present[0]//2==0 else 1
                    a,b=(p00,p01) if row==0 else (p10,p11)
                    if a and b==H(a,width):
                        target=ri+1 if row==0 else ri
                        pa,pb=(V(a,height),V(b,height))
                        fill(color,target,ci,pa); fill(color,target,ci+1,pb)

        # Within each panel row, complete a single motif by reflecting it into
        # the adjacent empty panel. This also handles motifs at outer edges.
        for ri,(r0,r1) in enumerate(rp):
            for ci in range(len(cp)-1):
                left=get(color,ri,ci); right=get(color,ri,ci+1)
                c0,c1=cp[ci]; d0,d1=cp[ci+1]
                width=c1-c0
                if width != d1-d0: continue
                if left and not right:
                    fill(color,ri,ci+1,H(left,width))
                elif right and not left:
                    fill(color,ri,ci,H(right,width))
    return out
