    rp,cp=spans(h,hr),spans(w,vc)
    div={out[r][0] for r in hr}|{out[0][c] for c in vc}
    colors={v for row in out for v in row if v and v not in div}
    src=[row[:] for row in out]
    def motif(color,ri,ci):
        r0,r1=rp[ri];c0,c1=cp[ci]
        return {(r-r0,c-c0) for r in range(r0,r1) for c in range(c0,c1) if src[r][c]==color}
    def H(p,w):return {(r,w-1-c) for r,c in p}
    def V(p,h):return {(h-1-r,c) for r,c in p}
    def HV(p,h,w):return {(h-1-r,w-1-c) for r,c in p}
    for color in colors:
