 "content": "def transform(grid):
    """Complete a 2x2 panel block when three motifs are reflections of one shape."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    rowcuts = [r for r in range(h) if out[r][0] != 0 and len(set(out[r])) == 1]
    colcuts = [c for c in range(w) if out[0][c] != 0 and all(out[r][c] == out[0][c] for r in range(h))]

    def spans(n, cuts):
        edges = [-1] + cuts + [n]
        return [(edges[i] + 1, edges[i + 1]) for i in range(len(edges) - 1)]

    rows, cols = spans(h, rowcuts), spans(w, colcuts)
    dividers = {out[r][0] for r in rowcuts} | {out[0][c] for c in colcuts}
    colors = {v for row in out for v in row if v and v not in dividers}
    original = [row[:] for row in out]

    def shape(color, ri, ci):
        r0, r1 = rows[ri]
        c0, c1 = cols[ci]
        cells = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                 if original[r][c] == color]
        if not cells:
            return None
        minr = min(r for r, c in cells); minc = min(c for r, c in cells)
        norm = {(r-minr, c-minc) for r, c in cells}
        height = max(r for r, c in norm) + 1
        width = max(c for r, c in norm) + 1
        return norm, height, width, minr, minc

    def flip_h(cells, height, width):
        return {(r, width-1-c) for r,c in cells}

    def flip_v(cells, height, width):
        return {(height-1-r, c) for r,c in cells}

    def flip_hv(cells, height, width):
        return {(height-1-r, width-1-c) for r,c in cells}

    for color in colors:
        for ri in range(len(rows)-1):
            for ci in range(len(cols)-1):
                entries = [shape(color,ri,ci), shape(color,ri,ci+1),
                           shape(color,ri+1,ci), shape(color,ri+1,ci+1)]
                present = [i for i,e in enumerate(entries) if e is not None]
                if len(present) != 3:
                    continue
                # All corresponding motifs must have the same bounding-box dimensions.
                dims = {(entries[i][1], entries[i][2]) for i in present}
                if len(dims) != 1:
                    continue
                height,width = next(iter(dims))
                canonical = []
                for i in range(4):
                    if entries[i] is None:
                        canonical.append(None)
                    else:
                        cells = entries[i][0]
                        if i % 2: cells = flip_h(cells,height,width)
                        if i // 2: cells = flip_v(cells,height,width)
                        canonical.append(cells)
                base = canonical[present[0]]
                if not base or any(canonical[i] != base for i in present[1:]):
                    continue
                missing = next(i for i in range(4) if i not in present)
                predicted = set(base)
                if missing % 2: predicted = flip_h(predicted,height,width)
                if missing // 2: predicted = flip_v(predicted,height,width)
                # Anchor the predicted bounding box to the common observed location
                # within each panel (the motifs need not be centered in their panels).
                anchors=[]
                for i in present:
                    e=entries[i]
                    if e[0] == (flip_h(base,height,width) if i%2 else base) and i//2:
                        anchors.append((e[3],e[4]))
                    elif e[0] == (flip_v(base,height,width) if i//2 else base) and i%2:
                        anchors.append((e[3],e[4]))
                # For this task, motif bounding-box anchors are selected from the
                # matching counterpart panels: use the modal row/column start.
                top_starts=[entries[i][3] for i in present if i//2==0]
                bottom_starts=[entries[i][3] for i in present if i//2==1]
                left_starts=[entries[i][4] for i in present if i%2==0]
                right_starts=[entries[i][4] for i in present if i%2==1]
                tr = (bottom_starts[0] if missing//2 and bottom_starts else top_starts[0] if top_starts else 0)
                tc = (right_starts[0] if missing%2 and right_starts else left_starts[0] if left_starts else 0)
                panel_r0 = rows[ri + missing//2][0]
                panel_c0 = cols[ci + missing%2][0]
                for r,c in predicted:
                    rr,cc=panel_r0+tr+r,panel_c0+tc+c
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                        out[rr][cc] = color
    return out
