    """Complete a reflected motif in the 2x2 block if 3 panels have it."""
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    hr=[r for r in range(h) if out[r][0] and len(set(out[r]))==1]
    vc=[c for c in range(w) if out[0][c] and all(out[r][c]==out[0][c] for r in range(h))]
    def spans(n,cuts):
        e=[-1]+cuts+[n]
        return [(e[i]+1,e[i+1]) for i in range(len(e)-1)]
    rp,cp=spans(h,hr),spans(w,vc)
    div={out[r][0] for r in hr}|{out[0][c] for c in vc}
    colors={v for row in out for v in row if v and v not in div}
    src=[r[:] for r in out]
    def pattern(color,ri,ci):
        r0,r1=rp[ri];c0,c1=cp[ci]
        pts=[(r-r0,c-c0) for r in range(r0,r1) for c in range(c0,c1) if src[r][c]==color]
        if not pts:return None
        ar=min(r for r,c in pts);ac=min(c for r,c in pts)
        pts={(r-ar,c-ac) for r,c in pts}
        return pts, max(r for r,c in pts)+1, max(c for r,c in pts)+1, ar, ac
    for color in colors:
      for ri in range(len(rp)-1):
       for ci in range(len(cp)-1):
        E=[pattern(color,ri,ci),pattern(color,ri,ci+1),pattern(color,ri+1,ci),pattern(color,ri+1,ci+1)]
        occ=[i for i,e in enumerate(E) if e]
        if len(occ)!=3 or len({(E[i][1],E[i][2]) for i in occ})!=1:continue
        hh,ww=E[occ[0]][1:3]
        H=lambda p:{(r,ww-1-c) for r,c in p}
        V=lambda p:{(hh-1-r,c) for r,c in p}
        HV=lambda p:{(hh-1-r,ww-1-c) for r,c in p}
        canon=[]
        for i,e in enumerate(E):
            if e is None:canon.append(None);continue
            p=e[0]
            if i%2:p=H(p)
            if i//2:p=V(p)
            canon.append(p)
        base=canon[occ[0]]
        if any(canon[i]!=base for i in occ):continue
        miss=next(i for i in range(4) if i not in occ)
        p=[base,H(base),V(base),HV(base)][miss]
        # Choose positional translation by the corresponding horizontal/vertical pair.
        same_row=[E[i] for i in occ if i//2==miss//2]
        same_col=[E[i] for i in occ if i%2==miss%2]
        if same_row: ar,ac=same_row[0][3],same_row[0][4]
        elif same_col: ar,ac=same_col[0][3],same_col[0][4]
        else: ar,ac=E[occ[0]][3],E[occ[0]][4]
        r0=rp[ri+miss//2][0];c0=cp[ci+miss%2][0]
        for r,c in p:
            rr,cc=r0+ar+r,c0+ac+c
            if rr<h and cc<w and out[rr][cc]==0:out[rr][cc]=color
    return out
