    out = [row[:] for row in grid]
    # Panels are 5x5 cells, separated by full 8-colored lines.
    rows = [(0,5),(6,11),(12,17),(18,23)]
    cols = [(0,5),(6,11),(12,17),(18,23)]
    colors = {v for row in out for v in row if v not in (0,8)}

    def panel(color, ri, ci):
        r0,r1=rows[ri]; c0,c1=cols[ci]
        return {(r-r0,c-c0) for r in range(r0,r1) for c in range(c0,c1)
                if out[r][c]==color}

    def hflip(p): return {(r,4-c) for r,c in p}
    def vflip(p): return {(4-r,c) for r,c in p}
    def hvflip(p): return {(4-r,4-c) for r,c in p}

    for color in colors:
        for ri in range(3):
            for ci in range(3):
                pats=[panel(color,ri,ci),panel(color,ri,ci+1),
                      panel(color,ri+1,ci),panel(color,ri+1,ci+1)]
                occupied=[i for i,p in enumerate(pats) if p]
                if len(occupied)!=3: continue
                canon=[pats[0],hflip(pats[1]),vflip(pats[2]),hvflip(pats[3])]
                base=canon[occupied[0]]
                if not base or any(canon[i]!=base for i in occupied[1:]): continue
                missing=next(i for i in range(4) if i not in occupied)
                predicted=[base,hflip(base),vflip(base),hvflip(base)][missing]
                tr,tc=ri+missing//2,ci+missing%2
                r0=rows[tr][0];c0=cols[tc][0]
                for r,c in predicted:
                    if out[r0+r][c0+c]==0: out[r0+r][c0+c]=color
    return out
